mapper.select:
SELECT BILL_ID, BILL_NUMBER, BILL_TYPE, BILL_AMOUNT, CURRENCY, ISSUE_DATE, MATURITY_DATE, DRAWER_NAME, DRAWER_ACCOUNT, PAYEE_NAME, PAYEE_ACCOUNT, ACCEPTOR_NAME, ACCEPTING_BANK, BILL_STATUS, BILL_PURPOSE, BILL_SOURCE, STORAGE_LOCATION, REGISTRAR_ID, REGISTRAR_NAME, REMARK, CREATE_TIME, UPDATE_TIME, CREATE_BY, UPDATE_BY, COMPANY_ID, DEPT_ID FROM TBL_BILL_REGISTRATION WHERE DELETE_FLAG = 0
AND BILL_NUMBER LIKE CONCAT('%', #{query.billNumber}, '%')
AND BILL_TYPE = #{query.billType}
AND BILL_STATUS = #{query.billStatus}
AND DRAWER_NAME LIKE CONCAT('%', #{query.drawerName}, '%')
AND PAYEE_NAME LIKE CONCAT('%', #{query.payeeName}, '%')
AND ACCEPTING_BANK LIKE CONCAT('%', #{query.acceptingBank}, '%')
AND BILL_AMOUNT >= #{query.minAmount}
AND BILL_AMOUNT <= #{query.maxAmount}
AND ISSUE_DATE >= #{query.issueStartDate}
AND ISSUE_DATE <= #{query.issueEndDate}
AND MATURITY_DATE >= #{query.maturityStartDate}
AND MATURITY_DATE <= #{query.maturityEndDate}
AND COMPANY_ID = #{query.companyId}
AND DEPT_ID = #{query.deptId}
ORDER BY CREATE_TIME DESC

SELECT TO_CHAR(CREATE_TIME, 'MM/DD') AS dateLabel, COUNT(*) AS count, COALESCE(SUM(BILL_AMOUNT), 0) AS amount FROM TBL_BILL_REGISTRATION WHERE DELETE_FLAG = 0
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
GROUP BY TO_CHAR(CREATE_TIME, 'MM/DD'), TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') ORDER BY TO_CHAR(CREATE_TIME, 'YYYY-MM-DD') ASC
